import{_ as i,a0 as p,w as u,s as a,ao as l,I as s,x as e,a1 as r,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"為防止對開源供應鏈的攻擊，GitHub 在行動 | LCTT x X-CMD","titleTemplate":false,"description":"為防止對開源供應鏈的攻擊，GitHub 在行動 | LCTT (202208) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為防止對開源供應鏈的攻擊，GitHub 在行動 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為防止對開源供應鏈的攻擊，GitHub 在行動 | LCTT (202208) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202208/20220809 Github Takes Action To Prevent Supply Chain Attacks On Open Source","title":"為防止對開源供應鏈的攻擊，GitHub 在行動","tag":"202208","desc":""},"relativePath":"202208/20220809 Github Takes Action To Prevent Supply Chain Attacks On Open Source.md","filePath":"[post].md"}'),d={name:"202208/20220809 Github Takes Action To Prevent Supply Chain Attacks On Open Source.md"};function T(m,t,b,f,g,S){const o=p("Link");return u(),a("div",null,[t[15]||(t[15]=l('<h1 id="為防止對開源供應鏈的攻擊-github-在行動" tabindex="-1">為防止對開源供應鏈的攻擊，GitHub 在行動 <a class="header-anchor" href="#為防止對開源供應鏈的攻擊-github-在行動" aria-label="Permalink to “為防止對開源供應鏈的攻擊，GitHub 在行動”">​</a></h1><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/08/github-cover-1-1068x601.jpg" alt=""></p><p>在 2020 年 SolarWinds 網絡間諜活動之後，一系列進一步的軟件供應鏈漏洞凸顯了確保軟件監管鏈安全的必要性。在這場間諜活動中，俄羅斯黑客滲透到一個廣泛使用的 IT 管理平台，並將受污染的升級程序悄悄帶入其中。由於開源項目從根本上來説是分散的，而且經常是臨時的活動，因此在這種背景下，這個問題尤其緊迫。GitHub 著名的 npm 註冊中心廣泛使用的 JavaScript 軟件包遭到一系列令人不安的黑客攻擊後，該公司前不久公佈了一項戰略，以提供更好的開源安全保護。</p><p>代碼簽名平台 Sigstore 將由微軟旗下的 GitHub 支持，以用於 npm 軟件包。代碼簽名類似於數字蠟封。為了讓開源維護者更加容易地確認他們編寫的代碼是否與全球範圍內人們實際下載的軟件包中最終包含的代碼相同，跨行業協作促成了該工具的創建。</p><p>GitHub 並不是開源生態系統的唯一組成部分，但 Sigstore 的聯合開發者、Chainguard 的首席執行官 Dan Lorenc 指出，它是社區的一個重要樞紐，因為絕大多數項目都在這裏存儲和共享源代碼。然而，當開發人員真正想下載開源軟件或工具時，他們通常會通過軟件包管理進行。</p><p>通過讓包管理器可以使用 Sigstore，開發人員可以在 Sigstore 工具的幫助下，在軟件通過供應鏈時處理加密檢查和要求。這增加了產品流通過程中每個階段的透明度。Lorenc 説，許多人在得知這些完整性檢查尚未實施時感到震驚，開源生態系統中相當大的一部分長期以來一直依賴於盲目的信心。拜登政府於 2021 年 5 月發佈了一項行政命令，主要涉及軟件供應鏈安全問題。</p><p>Linux 基金會、谷歌、紅帽、Purdue Universit 和 Chainguard 都對 Sigstore 的開發做出了貢獻。現在有了使用 Sigstore 為 Python 包發行版簽名的官方軟件，而且開發軟件的開源環境 Kubernetes 現在也支持它。</p><p>Sigstore 依靠免費和簡單易用來鼓勵採用，就像主要行業推動 HTTPS 網絡加密一樣，這在很大程度上是由非營利組織<ruby>互聯網安全研究組<rt>Internet Security Research Group</rt></ruby>的 Let&#39;s Encrypt 等工具實現的。據 GitHub 稱，該項目會首先提出 Sigstore 將如何在 npm 中實現的建議，並在開放評論期徵求社區人員對該工具的精確部署策略的意見。然而，最終的目標是讓這樣的代碼簽名能夠被儘可能多的開源項目使用，從而讓對供應鏈的攻擊更加困難。</p><p>GitHub 的 Hutchings 説：“我們希望看到這樣一個世界，最終所有的軟件工件都被簽名並鏈接回源代碼，這就是為什麼構建像 Sigstore 這樣的開放技術棧是如此重要，其他打包存儲庫也可以採用這種技術。”</p><hr>',10)),s("p",null,[t[1]||(t[1]=e("via: ",-1)),r(o,{href:"https://www.opensourceforu.com/2022/08/github-takes-action-to-prevent-supply-chain-attacks-on-open-source/"},{default:n(()=>[...t[0]||(t[0]=[e("https://www.opensourceforu.com/2022/08/github-takes-action-to-prevent-supply-chain-attacks-on-open-source/",-1)])]),_:1})]),s("p",null,[t[6]||(t[6]=e("作者：",-1)),r(o,{href:"https://www.opensourceforu.com/author/laveesh-kocher/"},{default:n(()=>[...t[2]||(t[2]=[e("Laveesh Kocher",-1)])]),_:1}),t[7]||(t[7]=e(" 選題：",-1)),r(o,{href:"https://github.com/lkxed"},{default:n(()=>[...t[3]||(t[3]=[e("lkxed",-1)])]),_:1}),t[8]||(t[8]=e(" 譯者：",-1)),r(o,{href:"https://github.com/lzx916"},{default:n(()=>[...t[4]||(t[4]=[e("lzx916",-1)])]),_:1}),t[9]||(t[9]=e(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[5]||(t[5]=[e("wxy",-1)])]),_:1})]),s("p",null,[t[12]||(t[12]=e("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[10]||(t[10]=[e("LCTT",-1)])]),_:1}),t[13]||(t[13]=e(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:n(()=>[...t[11]||(t[11]=[e("Linux中國",-1)])]),_:1}),t[14]||(t[14]=e(" 榮譽推出",-1))])])}const x=i(d,[["render",T]]);export{k as __pageData,x as default};
